import React from "react";
import Myinfo from "./myInfoProfileComponent";
import Posts from "./postsComponenet";
import Otherinfo from "./otherInfoProfileComponent";

class Profile extends React.Component {
    constructor(props){
        super(props);
        this.state = {
            loading:true,
            user: null,
            posts: null,
            post: null,
            base_URL: ""
        };
    }

    componentDidMount() {
        let token = localStorage.getItem("token");

        if (!token) {
            window.location.href = "/login";
            return;
        }

        fetch("http://localhost:8000/api/profile", {
            headers: {
                "Accept": "application/json",
                "Authorization": "Bearer " + token
            }
        })
        .then(res => res.json())
        .then(json => {
            this.setState({
                user: json.user,
                posts: json.posts,

                base_URL: json.base_URL,
                loading:false
            });
        })
        .catch(err => console.log("ERR:", err));
    }
    render() {
        if(this.state.loading!=false){
            return(
                <h1>salam</h1>
            );
        }else{
        return (
            <>
                <main className="container mt-4 pt-5">
                    <div className="container-fluid mt-5">
                        <div className="container p-4 item-back border rounded-5">
                            <Myinfo
                                userName={this.state.user.name}
                                postCount={this.state.postCount}
                                bio={this.state.user.bio}
                                profile={this.state.user.img}
                                base_URL={this.state.base_URL}
                            />
                            <div className="d-flex flex-wrap gap-4 mb-4">
                                <div className="text-center">
                                    <a href="highlight.php?id=1" className="text-decoration-none">
                                        <div className="ratio ratio-1x1" style={{width: "80px"}}>
                                            <img src="../img/s25.jpg" alt="Travel" className="rounded-circle border w-100 h-100 object-fit-cover"/>
                                        </div>
                                        <p className="small text-muted mt-2">Travel</p>
                                    </a>
                                </div>
                                <div className="text-center">
                                    <a href="highlight.php?id=2" className="text-decoration-none">
                                        <div className="ratio ratio-1x1" style={{width: "80px"}}>
                                            <img src="../img/s25.jpg" alt="Design" className="rounded-circle border w-100 h-100 object-fit-cover"/>
                                        </div>
                                        <p className="small text-muted mt-2">Design</p>
                                    </a>
                                </div>
                                <div className="text-center">
                                    <a href="highlight.php?id=3" className="text-decoration-none">
                                        <div className="ratio ratio-1x1" style={{width: "80px"}}>
                                            <img src="../img/s25.jpg" alt="Code" className="rounded-circle border w-100 h-100 object-fit-cover"/>
                                        </div>
                                        <p className="small text-muted mt-2">Code</p>
                                    </a>
                                </div>
                            </div>
                            <div className="row row-cols-1 row-cols-md-2 row-cols-xl-3 g-4">
                                <Posts/>
                                <Posts/>
                                <Posts/>
                                <Posts/>
                                <Posts/>
                                <Posts/>
                                <Posts/>
                                <Posts/>
                                <Posts/>
                                <Posts/>
                            </div>
                        </div>
                    </div>
                </main>
            </>
        );
    }
    }
}
export default Profile;
